"use client";

import { API_URL } from "@/lib/api";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

const emptySection = {
    heading: "",
    content: "",
};

export default function NewBlogPage() {
    const router = useRouter();

    const [products, setProducts] = useState([]);
    const [topic, setTopic] = useState("");
    const [generatingAI, setGeneratingAI] = useState(false);
    const [saving, setSaving] = useState(false);
    const [message, setMessage] = useState("");

    const [form, setForm] = useState({
        title: "",
        slug: "",
        excerpt: "",
        introduction: "",
        coverImage: "",
        category: "SaaS",
        tags: "",
        sections: [{ ...emptySection }],
        conclusion: "",
        relatedProducts: [],
        author: "SaaSpin Team",
        readTime: 5,
    });

    useEffect(() => {
        const token = localStorage.getItem("adminToken");

        if (!token) {
            router.push("/login");
            return;
        }

        loadProducts();
    }, []);

    async function loadProducts() {
        try {
            const response = await fetch(
                `${API_URL}/products`
            );

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.message || "Could not load products.");
            }

            setProducts(Array.isArray(data) ? data : []);
        } catch (error) {
            setMessage(error.message);
        }
    }

    function createSlug(value) {
        return value
            .toLowerCase()
            .trim()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "");
    }

    function handleChange(event) {
        const { name, value } = event.target;

        setForm((previous) => ({
            ...previous,
            [name]: value,
            ...(name === "title"
                ? {
                    slug: createSlug(value),
                }
                : {}),
        }));
    }

    function toggleProduct(productId) {
        setForm((previous) => {
            const exists = previous.relatedProducts.includes(productId);

            return {
                ...previous,
                relatedProducts: exists
                    ? previous.relatedProducts.filter((id) => id !== productId)
                    : [...previous.relatedProducts, productId],
            };
        });
    }

    function updateSection(index, field, value) {
        setForm((previous) => {
            const sections = [...previous.sections];

            sections[index] = {
                ...sections[index],
                [field]: value,
            };

            return {
                ...previous,
                sections,
            };
        });
    }

    function addSection() {
        setForm((previous) => ({
            ...previous,
            sections: [...previous.sections, { ...emptySection }],
        }));
    }

    function removeSection(index) {
        setForm((previous) => ({
            ...previous,
            sections: previous.sections.filter((_, i) => i !== index),
        }));
    }

    async function generateWithAI() {
        if (!topic.trim()) {
            setMessage("Enter a blog topic first.");
            return;
        }

        const token = localStorage.getItem("adminToken");

        try {
            setGeneratingAI(true);
            setMessage("Generating blog draft with AI...");

            const response = await fetch(
                `${API_URL}/ai/blogs/generate`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },

                    body: JSON.stringify({
                        topic,
                        category: form.category,
                        productIds: form.relatedProducts,
                    }),
                }
            );

            if (response.status === 401 || response.status === 403) {
                localStorage.removeItem("adminToken");

                setMessage(
                    "Your admin session has expired. Please log in again."
                );

                setTimeout(() => {
                    router.push("/login");
                }, 1200);

                return;
            }

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.message || "AI generation failed.");
            }

            const generated = data.blog;

            setForm((previous) => ({
                ...previous,

                title: generated.title || "",
                slug: generated.slug || "",
                excerpt: generated.excerpt || "",
                introduction: generated.introduction || "",

                category:
                    generated.category ||
                    previous.category,

                tags: Array.isArray(generated.tags)
                    ? generated.tags.join(", ")
                    : "",

                sections:
                    Array.isArray(generated.sections) &&
                        generated.sections.length > 0
                        ? generated.sections
                        : [{ ...emptySection }],

                conclusion: generated.conclusion || "",

                readTime:
                    generated.readTime || 5,

                // Keep admin-selected products.
                relatedProducts:
                    previous.relatedProducts,
            }));

            setMessage(
                `AI draft generated${data.model ? ` using ${data.model}` : ""}. Review it before saving.`
            );
        } catch (error) {
            setMessage(error.message);
        } finally {
            setGeneratingAI(false);
        }
    }

    async function handleSubmit(event) {
        event.preventDefault();

        if (!form.title.trim()) {
            setMessage("Blog title is required.");
            return;
        }

        if (!form.excerpt.trim()) {
            setMessage("Excerpt is required.");
            return;
        }

        if (!form.introduction.trim()) {
            setMessage("Introduction is required.");
            return;
        }

        if (!form.conclusion.trim()) {
            setMessage("Conclusion is required.");
            return;
        }

        const token = localStorage.getItem("adminToken");

        try {
            setSaving(true);
            setMessage("");

            const payload = {
                ...form,

                tags: form.tags
                    .split(",")
                    .map((tag) => tag.trim())
                    .filter(Boolean),

                sections: form.sections
                    .map((section) => ({
                        heading: section.heading.trim(),
                        content: section.content.trim(),
                    }))
                    .filter(
                        (section) =>
                            section.heading &&
                            section.content
                    ),

                readTime: Number(form.readTime) || 5,
            };

            const response = await fetch(
                `${API_URL}/blogs`,
                {
                    method: "POST",

                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },

                    body: JSON.stringify(payload),
                }
            );

            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.message || "Could not save blog.");
            }

            router.push("/admin/blogs");
        } catch (error) {
            setMessage(error.message);
        } finally {
            setSaving(false);
        }
    }

    return (
        <main className="admin-page">

            {/* =========================
        PAGE HEADER
    ========================== */}

            <div className="admin-page-header">
                <div>
                    <p className="admin-eyebrow">Content Management</p>

                    <div
                        style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "12px",
                        }}
                    >
                        <h1>Create New Blog</h1>

                        <span className="blog-draft-badge">
                            Draft
                        </span>
                    </div>

                    <p>
                        Create an article manually or use AI to generate
                        an editable first draft.
                    </p>
                </div>

                <Link
                    href="/admin/blogs"
                    className="admin-secondary-button"
                >
                    ← Back to Blogs
                </Link>
            </div>

            {/* =========================
        MESSAGE
    ========================== */}

            {message && (
                <div className="admin-message">
                    {message}
                </div>
            )}

            <form onSubmit={handleSubmit}>

                <div className="blog-editor-layout">

                    {/* ==================================
            LEFT SIDE
        =================================== */}

                    <div className="blog-editor-main">

                        {/* BASIC ARTICLE INFORMATION */}

                        <section className="blog-editor-card">

                            <div className="blog-editor-card-header">
                                <h2>Article</h2>

                                <p>
                                    Write the main information readers will see
                                    on the blog.
                                </p>
                            </div>

                            {/* TITLE */}

                            <div className="blog-form-group">
                                <label htmlFor="blog-title">
                                    Blog Title
                                </label>

                                <input
                                    id="blog-title"
                                    className="blog-title-input"
                                    name="title"
                                    type="text"
                                    value={form.title}
                                    onChange={handleChange}
                                    placeholder="Example: How AI Task Management Helps Small Teams"
                                    required
                                />
                            </div>

                            {/* SLUG */}

                            <div className="blog-form-group">
                                <label htmlFor="blog-slug">
                                    URL Slug
                                </label>

                                <input
                                    id="blog-slug"
                                    name="slug"
                                    type="text"
                                    value={form.slug}
                                    onChange={handleChange}
                                    placeholder="how-ai-task-management-helps-small-teams"
                                    required
                                />

                                <p className="blog-field-help">
                                    Used in the public blog URL. It is automatically
                                    generated from the title.
                                </p>
                            </div>

                            {/* EXCERPT */}

                            <div className="blog-form-group">
                                <label htmlFor="blog-excerpt">
                                    Excerpt
                                </label>

                                <textarea
                                    id="blog-excerpt"
                                    name="excerpt"
                                    value={form.excerpt}
                                    onChange={handleChange}
                                    rows="3"
                                    placeholder="Write a short summary of the article..."
                                    required
                                />

                                <p className="blog-field-help">
                                    This summary can appear on blog cards and search
                                    results.
                                </p>
                            </div>

                            {/* INTRODUCTION */}

                            <div className="blog-form-group">
                                <label htmlFor="blog-introduction">
                                    Introduction
                                </label>

                                <textarea
                                    id="blog-introduction"
                                    name="introduction"
                                    value={form.introduction}
                                    onChange={handleChange}
                                    rows="7"
                                    placeholder="Introduce the topic and explain what the reader will learn..."
                                    required
                                />
                            </div>

                        </section>


                        {/* ==================================
              ARTICLE SECTIONS
          =================================== */}

                        <section className="blog-editor-card">

                            <div className="blog-editor-card-header">
                                <h2>Article Sections</h2>

                                <p>
                                    Organize your article into clear sections.
                                    AI-generated sections can also be edited here.
                                </p>
                            </div>

                            <div className="blog-sections-container">

                                {form.sections.map(
                                    (section, index) => (

                                        <div
                                            className="blog-section-editor"
                                            key={index}
                                        >

                                            <div className="blog-section-header">

                                                <h3>
                                                    Section {index + 1}
                                                </h3>

                                                {form.sections.length > 1 && (
                                                    <button
                                                        type="button"
                                                        className="blog-remove-section"
                                                        onClick={() =>
                                                            removeSection(index)
                                                        }
                                                    >
                                                        Remove
                                                    </button>
                                                )}

                                            </div>

                                            {/* SECTION HEADING */}

                                            <input
                                                type="text"
                                                value={section.heading}
                                                onChange={(event) =>
                                                    updateSection(
                                                        index,
                                                        "heading",
                                                        event.target.value
                                                    )
                                                }
                                                placeholder="Section heading"
                                            />

                                            {/* SECTION CONTENT */}

                                            <textarea
                                                value={section.content}
                                                onChange={(event) =>
                                                    updateSection(
                                                        index,
                                                        "content",
                                                        event.target.value
                                                    )
                                                }
                                                rows="8"
                                                placeholder="Write the section content..."
                                            />

                                        </div>

                                    )
                                )}

                            </div>

                            <div className="blog-add-section">

                                <button
                                    type="button"
                                    className="admin-secondary-button"
                                    onClick={addSection}
                                >
                                    + Add Section
                                </button>

                            </div>

                        </section>


                        {/* ==================================
              CONCLUSION
          =================================== */}

                        <section className="blog-editor-card">

                            <div className="blog-editor-card-header">
                                <h2>Conclusion</h2>

                                <p>
                                    Finish the article with a useful summary for
                                    the reader.
                                </p>
                            </div>

                            <div className="blog-form-group">

                                <textarea
                                    name="conclusion"
                                    value={form.conclusion}
                                    onChange={handleChange}
                                    rows="7"
                                    placeholder="Write the final conclusion..."
                                    required
                                />

                            </div>

                        </section>

                    </div>


                    {/* ==================================
            RIGHT SIDEBAR
        =================================== */}

                    <aside className="blog-editor-sidebar">

                        {/* ==================================
              AI BLOG WRITER
          =================================== */}

                        <section className="admin-ai-assistant-card">
                            <div className="admin-ai-assistant-header">
                                <div className="admin-ai-assistant-title">
                                    <span className="admin-ai-badge">Gemini AI</span>
                                    <h3 style={{ margin: 0, fontSize: "16px", fontWeight: "700", color: "#111827" }}>AI Blog Writer</h3>
                                </div>
                                <span className="admin-ai-status">Draft Assistant</span>
                            </div>

                            <p className="admin-ai-assistant-desc">
                                Gemini can generate a structured, editable article draft based on your topic and selected product context. You retain full editorial control before saving.
                            </p>

                            <div className="blog-form-group">
                                <label htmlFor="ai-blog-topic" style={{ fontWeight: "600", fontSize: "13px" }}>
                                    Blog Topic or Angle
                                </label>
                                <textarea
                                    id="ai-blog-topic"
                                    value={topic}
                                    onChange={(event) =>
                                        setTopic(event.target.value)
                                    }
                                    rows="4"
                                    placeholder="Example: How AI task management helps small teams streamline workflow"
                                />
                            </div>

                            <button
                                type="button"
                                className="admin-ai-action-btn"
                                onClick={generateWithAI}
                                disabled={generatingAI}
                            >
                                {generatingAI ? (
                                    <>
                                        <span className="admin-ai-spinner" />
                                        <span>Generating Article Draft...</span>
                                    </>
                                ) : (
                                    <>
                                        <span>✨</span>
                                        <span>Generate Blog Draft with AI</span>
                                    </>
                                )}
                            </button>

                            <div className="admin-ai-notice">
                                <span>ℹ</span>
                                <span>AI creates editable draft fields only. Content is never automatically published.</span>
                            </div>
                        </section>


                        {/* ==================================
              ARTICLE SETTINGS
          =================================== */}

                        <section className="blog-settings-card">

                            <h2>
                                Article Settings
                            </h2>


                            {/* CATEGORY */}

                            <div className="blog-form-group">

                                <label htmlFor="blog-category">
                                    Category
                                </label>

                                <input
                                    id="blog-category"
                                    name="category"
                                    value={form.category}
                                    onChange={handleChange}
                                    placeholder="Productivity"
                                />

                            </div>


                            {/* COVER IMAGE */}

                            <div className="blog-form-group">

                                <label htmlFor="cover-image">
                                    Cover Image
                                </label>

                                <input
                                    id="cover-image"
                                    name="coverImage"
                                    value={form.coverImage}
                                    onChange={handleChange}
                                    placeholder="/images/blogs/article.jpg"
                                />

                                <p className="blog-field-help">
                                    Enter an image path for now. Image upload can
                                    be added later.
                                </p>

                            </div>


                            {/* TAGS */}

                            <div className="blog-form-group">

                                <label htmlFor="blog-tags">
                                    Tags
                                </label>

                                <input
                                    id="blog-tags"
                                    name="tags"
                                    value={form.tags}
                                    onChange={handleChange}
                                    placeholder="AI, Productivity, SaaS"
                                />

                                <p className="blog-field-help">
                                    Separate tags with commas.
                                </p>

                            </div>


                            {/* AUTHOR */}

                            <div className="blog-form-group">

                                <label htmlFor="blog-author">
                                    Author
                                </label>

                                <input
                                    id="blog-author"
                                    name="author"
                                    value={form.author}
                                    onChange={handleChange}
                                />

                            </div>


                            {/* READ TIME */}

                            <div className="blog-form-group">

                                <label htmlFor="read-time">
                                    Read Time
                                </label>

                                <input
                                    id="read-time"
                                    name="readTime"
                                    type="number"
                                    min="1"
                                    value={form.readTime}
                                    onChange={handleChange}
                                />

                                <p className="blog-field-help">
                                    Estimated minutes.
                                </p>

                            </div>

                        </section>


                        {/* ==================================
              RELATED PRODUCTS
          =================================== */}

                        <section className="blog-settings-card">

                            <h2>
                                Related Products
                            </h2>

                            <p
                                className="blog-field-help"
                                style={{
                                    marginBottom: "16px",
                                }}
                            >
                                Select products before using AI. Gemini will
                                receive their stored information.
                            </p>


                            {products.length === 0 ? (

                                <div className="blog-no-products">
                                    No products available.
                                </div>

                            ) : (

                                <div className="blog-product-selector">

                                    {products.map((product) => {

                                        const selected =
                                            form.relatedProducts.includes(
                                                product._id
                                            );

                                        return (
                                            <label
                                                className="blog-product-option"
                                                key={product._id}
                                            >

                                                <input
                                                    type="checkbox"
                                                    checked={selected}
                                                    onChange={() =>
                                                        toggleProduct(
                                                            product._id
                                                        )
                                                    }
                                                />

                                                <span className="blog-product-option-content">

                                                    <strong>
                                                        {product.name}
                                                    </strong>

                                                    <small>
                                                        {product.shortDescription ||
                                                            product.description}
                                                    </small>

                                                </span>

                                            </label>
                                        );

                                    })}

                                </div>

                            )}

                        </section>

                    </aside>

                </div>


                {/* ==================================
          BOTTOM ACTIONS
      =================================== */}

                <div className="blog-editor-actions">

                    <Link
                        href="/admin/blogs"
                        className="admin-secondary-button"
                    >
                        Cancel
                    </Link>

                    <button
                        type="submit"
                        className="admin-primary-button blog-save-button"
                        disabled={saving}
                    >
                        {saving
                            ? "Saving..."
                            : "Save as Draft"}
                    </button>

                </div>

            </form>

        </main>
    );
}

"use client";

import AdminRecordTable, { AdminStatus } from "@/components/AdminRecordTable";

import { API_URL } from "@/lib/api";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";

export default function AdminBlogsPage() {
  const router = useRouter();

  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [actionLoading, setActionLoading] = useState(null);

  async function loadBlogs() {
    const token = localStorage.getItem("adminToken");

    if (!token) {
      router.push("/login");
      return;
    }

    try {
      const response = await fetch(`${API_URL}/blogs/admin/all`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (response.status === 401 || response.status === 403) {
        localStorage.removeItem("adminToken");
        localStorage.removeItem("admin");
        router.replace("/login");
        return;
      }

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Could not load blogs.");
      }

      setBlogs(Array.isArray(data) ? data : []);
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadBlogs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function togglePublish(blog) {
    const token = localStorage.getItem("adminToken");
    if (!token) {
      router.replace("/login");
      return;
    }
    try {
      setActionLoading(blog._id);
      setMessage("");
      setError("");

      const response = await fetch(`${API_URL}/blogs/${blog._id}/status`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Could not change blog status.");
      }

      setMessage(data.message);
      await loadBlogs();
    } catch (error) {
      setError(error.message);
    } finally {
      setActionLoading(null);
    }
  }

  async function deleteBlog(id) {
    const confirmed = window.confirm(
      "Are you sure you want to delete this blog?",
    );

    if (!confirmed) return;

    const token = localStorage.getItem("adminToken");
    if (!token) {
      router.replace("/login");
      return;
    }
    try {
      setActionLoading(id);
      setMessage("");
      setError("");

      const response = await fetch(`${API_URL}/blogs/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || "Could not delete blog.");
      }

      setMessage(data.message);
      await loadBlogs();
    } catch (error) {
      setError(error.message);
    } finally {
      setActionLoading(null);
    }
  }

  if (loading) {
    return (
      <main className="admin-page">
        <p>Loading blogs...</p>
      </main>
    );
  }

  return (
    <main className="admin-page">
      <div className="admin-page-header">
        <div>
          <p className="admin-eyebrow">Content Management</p>
          <h1>Blogs</h1>
          <p>Manage SaaSpin blog articles.</p>
        </div>

        <div className="admin-header-actions">
          <Link href="/admin/blogs/new" className="admin-primary-button">
            + New Blog
          </Link>
        </div>
      </div>

      {error && <div className="admin-error" role="alert">{error}</div>}
      {message && <div className="admin-message" role="status">{message}</div>}

      {blogs.length === 0 ? (
        <div className="admin-empty-state">
          <h2>No blogs yet</h2>
          <p>Create your first SaaSpin blog article.</p>

          <Link href="/admin/blogs/new" className="admin-primary-button">
            Create Blog
          </Link>
        </div>
      ) : (
        <AdminRecordTable label="Blogs" records={blogs} columns={[{label:'Article',render:blog=><><strong>{blog.title}</strong><p className="admin-table-description">{blog.excerpt}</p>{blog.readTime || 5} min read{blog.relatedProducts?.length > 0 && <p className="admin-table-description">Related: {blog.relatedProducts.map(product=>product.name).join(', ')}</p>}</>},{label:'Category',render:blog=>blog.category || 'SaaS'},{label:'Status',render:blog=><AdminStatus status={blog.isPublished ? 'Published' : 'Draft'} />}]} renderActions={(blog) => (<div className="admin-review-actions">
                <Link
                  href={`/admin/blogs/${blog._id}/edit`}
                  className="admin-secondary-button"
                >
                  Edit
                </Link>

                <button
                  type="button"
                  className="admin-secondary-button"
                  disabled={actionLoading === blog._id}
                  onClick={() => togglePublish(blog)}
                >
                  {actionLoading === blog._id
                    ? "Working..."
                    : blog.isPublished
                      ? "Unpublish"
                      : "Publish"}
                </button>

                {blog.isPublished && (
                  <Link
                    href={`/blogs/${blog.slug}`}
                    className="admin-secondary-button"
                    target="_blank"
                  >
                    View
                  </Link>
                )}

                <button
                  type="button"
                  className="admin-danger-button"
                  disabled={actionLoading === blog._id}
                  onClick={() => deleteBlog(blog._id)}
                >
                  Delete
                </button>
              </div>)} />
      )}
    </main>
  );
}

"use client";

import AdminRecordTable, { AdminStatus } from "@/components/AdminRecordTable";

import { API_URL } from "@/lib/api";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";

export default function AdminComparisonsPage() {
  const router = useRouter();

  const [comparisons, setComparisons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [workingId, setWorkingId] = useState(null);

  async function loadComparisons() {
    try {
      setLoading(true);
      setError("");
      setNotice("");

      const token = localStorage.getItem("adminToken");

      if (!token) {
        router.push("/login");
        return;
      }

      const response = await fetch(
        `${API_URL}/comparisons/admin/all`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
          cache: "no-store",
        }
      );

      if (
        response.status === 401 ||
        response.status === 403
      ) {
        localStorage.removeItem("adminToken");
        localStorage.removeItem("admin");

        router.push("/login");
        return;
      }

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message || "Could not load comparisons."
        );
      }

      setComparisons(data);
    } catch (error) {
      console.error(error);
      setError(error.message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadComparisons();
  }, []);

  // ==========================================
  // PUBLISH / UNPUBLISH
  // ==========================================

  async function handleStatus(comparison) {
    try {
      setWorkingId(comparison._id);
      setError("");
      setNotice("");

      const token = localStorage.getItem("adminToken");

      if (!token) {
        router.push("/login");
        return;
      }

      const response = await fetch(
        `${API_URL}/comparisons/${comparison._id}/status`,
        {
          method: "PATCH",

          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Could not change comparison status."
        );
      }

      await loadComparisons();
    } catch (error) {
      console.error(error);
      setError(error.message);
    } finally {
      setWorkingId(null);
    }
  }

  // ==========================================
  // DELETE
  // ==========================================

  async function handleDelete(comparisonId) {
    const confirmed = window.confirm(
      "Are you sure you want to delete this comparison?"
    );

    if (!confirmed) {
      return;
    }

    try {
      setWorkingId(comparisonId);
      setError("");
      setNotice("");

      const token = localStorage.getItem("adminToken");

      if (!token) {
        router.push("/login");
        return;
      }

      const response = await fetch(
        `${API_URL}/comparisons/${comparisonId}`,
        {
          method: "DELETE",

          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Could not delete comparison."
        );
      }

      setNotice("Comparison updated successfully.");
setComparisons((previous) =>
        previous.filter(
          (comparison) =>
            comparison._id !== comparisonId
        )
      );
    } catch (error) {
      console.error(error);
      setError(error.message);
    } finally {
      setWorkingId(null);
    }
  }

  // ==========================================
  // PAGE
  // ==========================================

  return (
    <main className="admin-reviews-page">
{notice && <div className="admin-success" role="status">{notice}</div>}

      <div className="admin-reviews-container">

        <div className="admin-reviews-header">

          <div>
            <span className="admin-reviews-label">
              ADMIN
            </span>

            <h1>Comparisons</h1>

            <p>
              Create, edit, publish and manage SaaS
              product comparisons.
            </p>
          </div>

          <div className="admin-header-actions">

            <Link
              href="/admin/comparisons/new"
              className="admin-primary-button"
            >
              + New Comparison
            </Link>

          </div>

        </div>

        {error && (
          <div className="admin-error-message" role="alert">
            {error}
          </div>
        )}

        {loading ? (
          <p>Loading comparisons...</p>
        ) : comparisons.length === 0 ? (

          <div className="admin-empty-state">

            <h3>No comparisons yet</h3>

            <p>
              Create your first software comparison.
            </p>

            <Link
              href="/admin/comparisons/new"
              className="admin-primary-button"
            >
              Create Comparison
            </Link>

          </div>

        ) : (

          <AdminRecordTable label="Comparisons" records={comparisons} columns={[{label:'Comparison',render:comparison=><><strong>{comparison.title}</strong><p className="admin-table-description">{comparison.excerpt}</p>{comparison.readTime || 5} min read</>},{label:'Products',render:comparison=><>{comparison.productA?.name || 'Product A'} vs {comparison.productB?.name || 'Product B'}</>},{label:'Status',render:comparison=><AdminStatus status={comparison.isPublished ? 'Published' : 'Draft'} />}]} renderActions={(comparison) => (<div className="admin-review-actions">

                    <Link
                      href={`/admin/comparisons/${comparison._id}/edit`}
                      className="admin-secondary-button"
                    >
                      Edit
                    </Link>

                    {comparison.isPublished && (
                      <Link
                        href={`/comparisons/${comparison.slug}`}
                        className="admin-secondary-button"
                        target="_blank"
                      >
                        View
                      </Link>
                    )}

                    <button
                      type="button"
                      className="admin-primary-button"
                      onClick={() =>
                        handleStatus(comparison)
                      }
                      disabled={workingId === comparison._id}
                    >
                      {workingId === comparison._id
                        ? "Working..."
                        : comparison.isPublished
                          ? "Unpublish"
                          : "Publish"}
                    </button>

                    <button
                      type="button"
                      className="admin-delete-button"
                      onClick={() =>
                        handleDelete(
                          comparison._id
                        )
                      }
                      disabled={workingId === comparison._id}
                    >
                      Delete
                    </button>

                  </div>)} />

        )}

      </div>

    </main>
  );
}

