"use client";

import { API_URL as API } from "@/lib/api";

import Link from "next/link";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";


const initialForm = {
  name: "",
  slug: "",
  description: "",
  shortDescription: "",
  website: "",
  logo: "",
  category: "",
  features: "",
  targetAudience: "",
  integrations: "",
  pricingInfo: "",
  strengths: "",
  limitations: "",
};

export default function NewProductPage() {
  const router = useRouter();

  const [formData, setFormData] =
    useState(initialForm);

  const [categories, setCategories] =
    useState([]);

  const [loading, setLoading] =
    useState(false);

  const [loadingCategories, setLoadingCategories] =
    useState(true);

  const [error, setError] =
    useState("");

  const [message, setMessage] =
    useState("");

  // ==========================================
  // CHECK AUTH + LOAD CATEGORIES
  // ==========================================

  useEffect(() => {
    const token =
      localStorage.getItem("adminToken");

    if (!token) {
      router.push("/login");
      return;
    }

    loadCategories();
  }, [router]);

  async function loadCategories() {
    try {
      setLoadingCategories(true);

      const response =
        await fetch(`${API}/categories`, {
          cache: "no-store",
        });

      const data =
        await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Could not load categories."
        );
      }

      setCategories(
        Array.isArray(data) ? data : []
      );
    } catch (error) {
      setError(error.message);
    } finally {
      setLoadingCategories(false);
    }
  }

  // ==========================================
  // CREATE SLUG
  // ==========================================

  function createSlug(value) {
    return value
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
  }

  // ==========================================
  // HANDLE INPUT
  // ==========================================

  function handleChange(event) {
    const {
      name,
      value,
    } = event.target;

    setFormData((current) => {
      const updated = {
        ...current,
        [name]: value,
      };

      // Automatically generate slug from name
      if (name === "name") {
        updated.slug =
          createSlug(value);
      }

      return updated;
    });
  }

  // ==========================================
  // STRING -> ARRAY
  // ==========================================

  function textToArray(value) {
    return value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  }

  // ==========================================
  // SUBMIT
  // ==========================================

  async function handleSubmit(event) {
    event.preventDefault();

    setError("");
    setMessage("");

    const token =
      localStorage.getItem("adminToken");

    if (!token) {
      router.push("/login");
      return;
    }

    if (
      !formData.name.trim() ||
      !formData.slug.trim() ||
      !formData.description.trim() ||
      !formData.website.trim() ||
      !formData.category
    ) {
      setError(
        "Name, slug, description, website and category are required."
      );

      return;
    }

    const payload = {
      name:
        formData.name.trim(),

      slug:
        formData.slug.trim(),

      description:
        formData.description.trim(),

      shortDescription:
        formData.shortDescription.trim(),

      website:
        formData.website.trim(),

      logo:
        formData.logo.trim(),

      category:
        formData.category,

      features:
        textToArray(
          formData.features
        ),

      targetAudience:
        textToArray(
          formData.targetAudience
        ),

      integrations:
        textToArray(
          formData.integrations
        ),

      pricingInfo:
        formData.pricingInfo.trim(),

      strengths:
        textToArray(
          formData.strengths
        ),

      limitations:
        textToArray(
          formData.limitations
        ),
    };

    try {
      setLoading(true);

      const response =
        await fetch(`${API}/products`, {
          method: "POST",

          headers: {
            "Content-Type":
              "application/json",

            Authorization:
              `Bearer ${token}`,
          },

          body:
            JSON.stringify(payload),
        });

      const data =
        await response.json();

      if (
        response.status === 401 ||
        response.status === 403
      ) {
        localStorage.removeItem(
          "adminToken"
        );

        localStorage.removeItem(
          "admin"
        );

        router.push("/login");
        return;
      }

      if (!response.ok) {
        throw new Error(
          data.message ||
            "Could not create product."
        );
      }

      setMessage(
        "Product created successfully."
      );

      setTimeout(() => {
        router.push(
          "/admin/products"
        );
      }, 700);
    } catch (error) {
      console.error(error);

      setError(
        error.message ||
          "Could not create product."
      );
    } finally {
      setLoading(false);
    }
  }

  // ==========================================
  // PAGE
  // ==========================================

  return (
    <main className="product-editor-page">

      <div className="product-editor-container">

        {/* HEADER */}

        <div className="product-editor-header">

          <div>
            <p className="product-editor-eyebrow">
              Product Management
            </p>

            <h1>Add Product</h1>

            <p>
              Add verified product information
              that can later be used for deals
              and AI-assisted reviews.
            </p>
          </div>

          <Link
            href="/admin/products"
            className="admin-secondary-button"
          >
            ← Products
          </Link>

        </div>

        {/* ERROR */}

        {error && (
          <div className="product-editor-error">
            {error}
          </div>
        )}

        {/* SUCCESS */}

        {message && (
          <div className="product-editor-success">
            {message}
          </div>
        )}

        {/* FORM */}

        <form
          onSubmit={handleSubmit}
          className="product-editor-form"
        >

          {/* BASIC INFORMATION */}

          <section className="product-editor-section">

            <div className="product-editor-section-heading">
              <h2>
                Basic Information
              </h2>

              <p>
                Core information used
                throughout the website.
              </p>
            </div>

            <div className="product-form-grid">

              <div className="product-form-field">
                <label htmlFor="admin-field-name">
                  Product Name *
                </label>

                <input id="admin-field-name"
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  placeholder="Example: AI Writer"
                  required
                />
              </div>

              <div className="product-form-field">
                <label htmlFor="admin-field-slug">
                  Slug *
                </label>

                <input id="admin-field-slug"
                  type="text"
                  name="slug"
                  value={formData.slug}
                  onChange={handleChange}
                  placeholder="ai-writer"
                  required
                />

                <small>
                  Automatically generated
                  from the product name.
                </small>
              </div>

              <div className="product-form-field">
                <label htmlFor="admin-field-category">
                  Category *
                </label>

                <select id="admin-field-category"
                  name="category"
                  value={formData.category}
                  onChange={handleChange}
                  required
                  disabled={
                    loadingCategories
                  }
                >
                  <option value="">
                    {loadingCategories
                      ? "Loading categories..."
                      : "Select category"}
                  </option>

                  {categories.map(
                    (category) => (
                      <option
                        key={category._id}
                        value={category._id}
                      >
                        {category.name}
                      </option>
                    )
                  )}
                </select>
              </div>

              <div className="product-form-field">
                <label htmlFor="admin-field-website">
                  Website *
                </label>

                <input id="admin-field-website"
                  type="url"
                  name="website"
                  value={formData.website}
                  onChange={handleChange}
                  placeholder="https://example.com"
