                        <th>
                          {productAName}
                        </th>

                        <th>
                          {productBName}
                        </th>
                      </tr>
                    </thead>

                    <tbody>

                      {comparison.comparisonPoints.map(
                        (point, index) => (
                          <tr key={index}>

                            <th>
                              {point.title}
                            </th>

                            <td>
                              {point.productA}
                            </td>

                            <td>
                              {point.productB}
                            </td>

                          </tr>
                        )
                      )}

