                  </table>

                </div>

              </article>
            )}

            {/* BEST FOR */}

            <article className="comparison-content-section">

              <h2>Which one is best for you?</h2>

              <div className="comparison-two-columns">

                <div className="comparison-info-box">

                  <h3>
                    {productAName} is best for
